import{z as B,x as i,o as A,c as d,q as n,j as s,D as r,d as E,s as t,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"社区基准的公信力","description":"","frontmatter":{"title":"社区基准的公信力","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eco-community-benchmark-credibility.md","filePath":"llm/eco-community-benchmark-credibility.md","lastUpdated":1791063341000}'),m={name:"llm/eco-community-benchmark-credibility.md"};function p(c,a,D,h,C,F){const l=i("Mermaid");return A(),d("div",null,[a[2]||(a[2]=n('<h1 id="社区基准的公信力" tabindex="-1">社区基准的公信力 <a class="header-anchor" href="#社区基准的公信力" aria-label="Permalink to &quot;社区基准的公信力&quot;">​</a></h1><div class="epigraph"><p>公信力是复算成本的反函数：第三方重算你的数字越便宜，你的分数越可信。</p><footer>—— 据 AlpacaEval 2 与 Arena-Hard 的长度控制、开放评测框架与社区榜单实践整理</footer></div><p><a href="/llm/eco-release-versioning">上一课</a>把版本钉死，数字从此有了锚。但发布方报出的数字天生带着动机——没人会在标题里写自己输了的那张卷子。社区怎么决定信谁的分数，是本课的问题：基准的公信力从哪来，怎么被侵蚀，发布方怎么做才能让数字站住。<a href="/llm/benchmark-saturation">基准饱和</a>已经写过「老卷会背」的降级逻辑，<a href="/llm/arena-hard">Arena-Hard 与 AlpacaEval 2</a> 已经写过裁判与长度的坑；本课把它们装进发布流程，写报分的纪律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发布方报分的公信力缺口有四个来源。<strong>选择性</strong>：挑赢的基准报，输的不提，读者没有损失函数无从察觉。<strong>协议缺失</strong>：只给数字不给 harness 版本、解码参数、是否思维链，同一个模型换个协议名次能差出十几位。<strong>污染与背题</strong>：训练语料见过公开测试集，分数测的是记忆；饱和卷继续挂榜让这个问题放大。<strong>尺子偏置</strong>：早期偏好类榜单的胜率可以被更长的回答推高，风格讨喜与能力领先混在一个数里。每一个来源都曾被真实榜单付过学费，社区的反制也由此长出来。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报分纪律三条，与四个缺口一一对应。<strong>协议完整披露</strong>：每个数字带 harness 与版本、解码参数、是否 CoT、测试集版本——这是上一课版本纪律在评测面的应用。<strong>可复算</strong>：用开放评测框架跑分并放出配置，让第三方一条命令重算；基座与指令模型分开报，自家协议与社区标准协议两列并列，输的那列也放出来。<strong>独立信号三角化</strong>：静态基准之外，交叉引用盲测竞技场这类发布方无法直接操作的信号，并说明其口径——竞技场测的是偏好强度，不测事实正确。<span class="marginnote">「三角化」借自测量学：一个点只用一把尺子量会有系统误差，用两把原理不同的尺子各量一次，交叉验证后才敢下结论。这里静态卷是「卷面考试」，竞技场是「真人盲测投票」，两者口径完全不同，结论一致时可信度才真正抬升——只信其中一把尺子，就会被它的盲区单方面说服。</span>社区榜单的分工也在此：固定 harness 的批量复评统一协议，竞技场提供分布外的真实流量，两者 disagree 的地方往往比 agree 的地方信息量大。</p>',7)),(A(),s(o,null,{default:r(()=>[t(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SELF%5B%22%E5%8F%91%E5%B8%83%E6%96%B9%E8%B7%91%E5%88%86%22%5D%20--%3E%20DIS%5B%22%E5%8D%8F%E8%AE%AE%E6%8A%AB%E9%9C%B2%EF%BC%9Aharness%E3%80%81%E8%A7%A3%E7%A0%81%E3%80%81CoT%22%5D%0A%20%20DIS%20--%3E%20RE%5B%22%E5%BC%80%E6%94%BE%E9%85%8D%E7%BD%AE%E5%8F%AF%E5%A4%8D%E7%AE%97%22%5D%0A%20%20RE%20--%3E%20IND%5B%22%E7%8B%AC%E7%AB%8B%E4%BF%A1%E5%8F%B7%E4%B8%89%E8%A7%92%E5%8C%96%EF%BC%9A%E5%A4%8D%E8%AF%84%E6%A6%9C%20%2B%20%E7%AB%9E%E6%8A%80%E5%9C%BA%22%5D%0A%20%20IND%20--%3E%20CON%5B%22%E5%88%86%E6%AD%A7%E5%A4%84%E5%AE%9A%E4%BD%8D%EF%BC%9A%E5%81%8F%E7%BD%AE%20%2F%20%E6%B1%A1%E6%9F%93%20%2F%20%E5%8D%8F%E8%AE%AE%E5%B7%AE%22%5D%0A%20%20CON%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%E5%88%86%E5%88%97%EF%BC%9A%E8%B5%A2%E5%8D%B7%E4%B8%8E%E8%BE%93%E5%8D%B7%E5%90%8C%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("公信力机制的核心是把「信任发布方」替换成「信任可重复的过程」。协议披露把复算成本从「逆向你的评测脚本」降到「装好框架、填配置」；可复算让任何一篇质疑都能落成一个具体的差异点——是版本、是解码还是测试集不同。长度与风格控制是尺子自身的修正：长度控制后的胜率把「答得多」从「答得好」里剥出去，这是偏好类指标能上发布物的前提。污染自证在训练侧完成：语料里的 "),e("a",{href:"/llm/canary-strings"},"canary 字符串"),E("让「见过没有」可以事后对账。三角化不是求平均，而是利用分歧：静态卷上的领先若在竞技场上消失，先查污染与协议，再谈能力。")],-1)),a[5]||(a[5]=e("p",null,"四个缺口各自长出了对应的反制手段，合起来构成一张「侵蚀—修复」对照表：",-1)),(A(),s(o,null,{default:r(()=>[t(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20SUB%5B%22%E9%80%89%E6%8B%A9%E6%80%A7%E6%8A%A5%E5%88%86%EF%BC%9A%E5%8F%AA%E6%8A%A5%E8%B5%A2%E5%8D%B7%22%5D%20--%3E%20C1%5B%22%E8%B5%A2%E5%8D%B7%E8%BE%93%E5%8D%B7%E5%90%8C%E8%A1%A8%E5%8F%91%E5%B8%83%22%5D%0A%20%20NOPRO%5B%22%E5%8D%8F%E8%AE%AE%E7%BC%BA%E5%A4%B1%EF%BC%9A%E6%95%B0%E5%AD%97%E4%B8%8D%E5%8F%AF%E6%AF%94%22%5D%20--%3E%20C2%5B%22harness%E3%80%81%E8%A7%A3%E7%A0%81%E3%80%81CoT%20%E6%8A%AB%E9%9C%B2%22%5D%0A%20%20POL%5B%22%E6%B1%A1%E6%9F%93%E8%83%8C%E9%A2%98%EF%BC%9A%E6%B5%8B%E7%9A%84%E6%98%AF%E8%AE%B0%E5%BF%86%22%5D%20--%3E%20C3%5B%22canary%20%E4%BA%8B%E5%90%8E%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20BIAS%5B%22%E5%B0%BA%E5%AD%90%E5%81%8F%E7%BD%AE%EF%BC%9A%E9%95%BF%E5%9B%9E%E7%AD%94%E5%88%B7%E5%88%86%22%5D%20--%3E%20C4%5B%22%E9%95%BF%E5%BA%A6%E4%B8%8E%E9%A3%8E%E6%A0%BC%E6%8E%A7%E5%88%B6%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">长度偏置有多真实？假设两个模型回答质量相同，A 每条都比 B 长两百字，未控制的胜率里这两百字会全被记成「更好」——裁判（人或模型）天然偏爱内容显得更充实的答案。长度控制就是把这笔虚账减掉：按长度差修正胜率后，「答得多」才不再冒充「答得好」。看任何偏好榜，先问一句这把尺子对长度打折了没。</span></p><p><span class="marginnote">AlpacaEval 2 引入长度控制胜率、Arena-Hard 控制风格影响，直接原因就是早期版本可以靠「更长、更格式化」刷胜率——发布分数前先问：这把尺子对长度打折了吗。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有任何单一数字收编全部能力：固定协议的榜单会漏新能力，竞技场的用户分布不代表你的目标用户，「社区公认」本身可以被营销预算部分制造。报分纪律约束发布方，也约束引用者：转发一张榜前先看它有没有协议列，没有协议的排行榜只是宣传物料。<span class="marginnote">初学者容易以为「同一模型在不同榜单分数接近，说明两边都测准了」，实际上恰恰相反：不同 harness 下同名模型的名次能差出十几位，分数接近可能只是协议碰巧相同。想自己复现一个分数时，第一步不是下载模型，而是核对协议四件套——框架版本、解码参数、是否思维链、测试集版本，缺一样复算就是盲跑。</span>饱和卷要在卡上降级——这不是可选项，<a href="/llm/model-cards">模型卡</a>的分栏要求早已写明。最后，公信力的上限由发布方的报告决定：分数之外，配方与负结果怎么写、承诺到哪一层，是下一课的主题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公信力四个侵蚀源：选择性报分、协议缺失、污染背题、尺子偏置；报分纪律三条与之对应。</li><li>协议完整披露是版本纪律在评测面的应用：harness 版本、解码、CoT、测试集版本随数字走。</li><li>开放配置可复算，把信任从「信人」换成「信可重复的过程」；输卷与赢卷同表。</li><li>偏好类数字必须过长度与风格控制；污染自证靠训练侧 canary。</li><li>静态榜与竞技场三角化，分歧处的信息量大于一致处。</li><li>出处：AlpacaEval 2 与 Arena-Hard 论文口径；开放评测框架与社区榜单实践，按本课程整理。</li></ul>',6))])}const f=B(m,[["render",p]]);export{g as __pageData,f as default};
